import{_ as d,o as a,c as r,ac as e}from"./chunks/framework.Bzw8ikz_.js";const g=JSON.parse('{"title":"分辨率","description":"","frontmatter":{},"headers":[],"relativePath":"front/realtime-media/index.md","filePath":"front/realtime-media/index.md","lastUpdated":1773017852000}'),s={name:"front/realtime-media/index.md"};function l(i,t,n,o,p,h){return a(),r("div",null,[...t[0]||(t[0]=[e(`<h1 id="分辨率" tabindex="-1">分辨率 <a class="header-anchor" href="#分辨率" aria-label="Permalink to &quot;分辨率&quot;">​</a></h1><p>视频分辨率跟我们平时说的图像分辨率差不多，主要是指<strong>单位英寸中所包含的像素点数。</strong> 可以用 <code>长 *宽</code>的形式表示比如 1280 * 720 的分辨率，也可以以像素点总数的形式表示，比如 <strong>200 万像素(1920 * 1080)</strong>。</p><h2 id="逐行扫描和隔行扫描" tabindex="-1">逐行扫描和隔行扫描 <a class="header-anchor" href="#逐行扫描和隔行扫描" aria-label="Permalink to &quot;逐行扫描和隔行扫描&quot;">​</a></h2><p>在视频制作中，可能你也会见到1080i 这个分辨率。你知道其中P 和 I的区别嘛？这个可能许多小伙伴就不清楚了。这个* <em>P是Progressive指的是逐行扫描， I是interlace指的是隔行扫描。</em>*</p><h1 id="帧率" tabindex="-1">帧率 <a class="header-anchor" href="#帧率" aria-label="Permalink to &quot;帧率&quot;">​</a></h1><p>帧率(Frame rate)=帧数(Frames)/时间(Time)单位为帧每秒(f/s, frames persecond, fps)。</p><h1 id="视频格式" tabindex="-1">视频格式 <a class="header-anchor" href="#视频格式" aria-label="Permalink to &quot;视频格式&quot;">​</a></h1><h2 id="封装格式" tabindex="-1">封装格式 <a class="header-anchor" href="#封装格式" aria-label="Permalink to &quot;封装格式&quot;">​</a></h2><p><strong>就是把视频数据和音频数据打包成一个文件的规范。</strong> 一个完整的视频文件，包括音频、视频和基础元信息 封装格式是不会影响视频的画质，封装成什么格式就看在使用的时候解码器是否支持这个封装格式即可</p><p><strong>常见视频封装格式对比表</strong></p><table tabindex="0"><thead><tr><th>封装格式</th><th>常见扩展名</th><th>常见编码</th><th>特点与用途</th><th>优点</th><th>缺点</th></tr></thead><tbody><tr><td><strong>MP4</strong></td><td>.mp4</td><td>H.264/H.265/AAC</td><td>最常见的通用视频封装</td><td>✅ 兼容性最好（网页、手机、电视全支持）✅ 适合在线视频分发和点播</td><td>❌ 流式播放能力一般，直播不是最优选择</td></tr><tr><td><strong>MKV</strong></td><td>.mkv</td><td>H.264/H.265/VP9/音轨多种</td><td>高扩展性、支持多音轨、字幕</td><td>✅ 支持 4K / HDR / 多音轨 / 字幕✅ 开源、封装灵活</td><td>❌ 浏览器播放兼容性较差</td></tr><tr><td><strong>MOV</strong></td><td>.mov</td><td>ProRes/H.264/H.265</td><td>苹果常用、常用于剪辑</td><td>✅ 高质量、适合专业制作</td><td>❌ 文件大、跨平台兼容性较差</td></tr><tr><td><strong>AVI</strong></td><td>.avi</td><td>旧式编码</td><td>老格式，逐渐淘汰</td><td>✅ 过去广泛使用</td><td>❌ 压缩效率低、文件体积大</td></tr><tr><td><strong>FLV</strong></td><td>.flv</td><td>H.264/AAC</td><td>Flash 时代网络视频封装</td><td>✅ 过去用于直播/点播</td><td>❌ Flash 淘汰，已基本退出历史舞台</td></tr><tr><td><strong>TS / M2TS</strong></td><td>.ts/.m2ts</td><td>H.264/H.265/AAC</td><td>流媒体常用封装（如 HLS 分片）</td><td>✅ 天生适合直播、切片传输</td><td>❌ 单文件播放不友好</td></tr><tr><td><strong>WEBM</strong></td><td>.webm</td><td>VP8/VP9/Opus</td><td>Google 开源，为网页优化</td><td>✅ 浏览器兼容好、体积小</td><td>❌ 苹果生态支持不如 mp4</td></tr><tr><td><strong>RMVB</strong></td><td>.rmvb</td><td>RealVideo</td><td>曾经很流行</td><td>✅ 小体积</td><td>❌ 过时，不再推荐</td></tr></tbody></table><h2 id="编码格式" tabindex="-1">编码格式 <a class="header-anchor" href="#编码格式" aria-label="Permalink to &quot;编码格式&quot;">​</a></h2><p><strong>视频编码格式本质上就是一种视频压缩技术</strong></p><p>因为原始视频数据太大（几秒钟就能几十GB），必须压缩，否则没办法存、没办法传、没办法播。 常见编码格式：<strong>H.264、H.265、VP9、AV1、MPEG2...</strong> 它们不是视频文件本身，而是<strong>压缩算法</strong>，决定：</p><ul><li>视频能压成多小</li><li>清晰度如何</li><li>网络传输快不快</li><li>CPU解码是否吃力</li></ul><p>举个例子：</p><table tabindex="0"><thead><tr><th>编码格式</th><th>同样 1080p 1 分钟视频大小</th></tr></thead><tbody><tr><td>MPEG-2</td><td>300 MB</td></tr><tr><td>H.264</td><td>~60 MB</td></tr><tr><td>H.265</td><td>~30 MB</td></tr><tr><td>AV1</td><td>~20 MB</td></tr></tbody></table><p>压缩内容之后，再用封装容器（MP4、MKV、TS）打包起来。</p><h1 id="码率" tabindex="-1">码率 <a class="header-anchor" href="#码率" aria-label="Permalink to &quot;码率&quot;">​</a></h1><p>码率（bitrate）是指单位时间内<strong>传输或处理的数据量</strong>，视频中就是每秒钟有多少“位”（bits）用于描述视频画面，**码率 = 每秒钟包含的比特数 **。</p><p>常见单位有：</p><ul><li><strong>bps</strong>：bit per second（比特/秒）</li><li><strong>Kbps</strong>：千比特/秒（1 Kbps = 1000 bps）</li><li><strong>Mbps</strong>：兆比特/秒（1 Mbps = 1000 Kbps）</li><li><strong>Gbps</strong>：千兆比特/秒</li></ul><p>注意： <strong>bit（位） ≠ byte（字节）</strong>，<strong>1 Byte = 8 bit</strong></p><p>因为音视频有一个<strong>致命特性</strong>：</p><blockquote><p><strong>音视频是「连续时间」的媒体</strong></p></blockquote><h3 id="码率有什么作用" tabindex="-1">码率有什么作用 <a class="header-anchor" href="#码率有什么作用" aria-label="Permalink to &quot;码率有什么作用&quot;">​</a></h3><ol><li>决定音视频质量</li></ol><ul><li><strong>码率越高 → 画质/音质越好</strong></li><li><strong>码率越低 → 失真、马赛克、杂音越多</strong></li></ul><p>例如：</p><ul><li>128 Kbps MP3：普通音质</li><li>320 Kbps MP3：高音质</li><li>4 Mbps 视频：清晰</li><li>20 Mbps 视频：高清 / 超清</li></ul><ol start="2"><li>决定文件大小</li></ol><p>在时长固定的情况下：</p><blockquote><p><strong>文件大小 ∝ 码率</strong></p></blockquote><p>码率高 → 文件大 码率低 → 文件小</p><ol start="3"><li>决定网络带宽需求</li></ol><p>直播、在线视频观看时<strong>码率越高，对网络速度要求越高</strong></p><p>例如：</p><ul><li>1080p 视频通常需要 <strong>5～8 Mbps</strong></li><li>4K 视频可能需要 <strong>25 Mbps 以上</strong></li></ul><p>举个再直白一点的例子：</p><p>两个视频都是：</p><ul><li>1080p</li><li>60fps</li><li>H.264</li></ul><p>但：</p><table tabindex="0"><thead><tr><th>场景</th><th>码率</th></tr></thead><tbody><tr><td>PPT / 会议画面</td><td>2 Mbps</td></tr><tr><td>足球比赛</td><td>12 Mbps</td></tr></tbody></table><p>因为：</p><ul><li>运动越剧烈</li><li>帧间差异越大</li><li>压缩效率越低</li><li><strong>必须用更高码率兜底画质</strong></li></ul><p><strong>总结</strong></p><blockquote><p><strong>码率就是“每秒吃多少数据”，决定了质量、体积和带宽需求。</strong></p></blockquote><h3 id="码率的换算" tabindex="-1">码率的换算 <a class="header-anchor" href="#码率的换算" aria-label="Permalink to &quot;码率的换算&quot;">​</a></h3><h4 id="码率-→-文件大小" tabindex="-1">码率 → 文件大小 <a class="header-anchor" href="#码率-→-文件大小" aria-label="Permalink to &quot;码率 → 文件大小&quot;">​</a></h4><p><strong>公式：</strong></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>文件大小 = 码率 × 时长 ÷ 8</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>例子：一个 <strong>10 分钟</strong>、<strong>128 Kbps</strong> 的音频文件：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>128 Kbps × 600 秒 ÷ 8</span></span>
<span class="line"><span>= 9600 KB</span></span>
<span class="line"><span>≈ 9.4 MB</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><hr><h4 id="文件大小-→-码率" tabindex="-1">文件大小 → 码率 <a class="header-anchor" href="#文件大小-→-码率" aria-label="Permalink to &quot;文件大小 → 码率&quot;">​</a></h4><p><strong>公式：</strong></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>码率 = 文件大小 × 8 ÷ 时长</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>例子：一个 <strong>100 MB</strong> 的视频，时长 <strong>10 分钟</strong>：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>100 MB × 8 ÷ 600 秒</span></span>
<span class="line"><span>≈ 1.33 Mbps</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="常见码率对照表" tabindex="-1">常见码率对照表 <a class="header-anchor" href="#常见码率对照表" aria-label="Permalink to &quot;常见码率对照表&quot;">​</a></h3><h4 id="🎵音频" tabindex="-1">🎵音频 <a class="header-anchor" href="#🎵音频" aria-label="Permalink to &quot;🎵音频&quot;">​</a></h4><table tabindex="0"><thead><tr><th>类型</th><th>常见码率</th></tr></thead><tbody><tr><td>语音通话</td><td>16–64 Kbps</td></tr><tr><td>MP3 普通</td><td>128 Kbps</td></tr><tr><td>MP3 高品质</td><td>320 Kbps</td></tr><tr><td>无损 FLAC</td><td>800–1400 Kbps</td></tr></tbody></table><h4 id="🎬视频" tabindex="-1">🎬视频 <a class="header-anchor" href="#🎬视频" aria-label="Permalink to &quot;🎬视频&quot;">​</a></h4><table tabindex="0"><thead><tr><th>分辨率</th><th>常见码率</th></tr></thead><tbody><tr><td>480p</td><td>1–2 Mbps</td></tr><tr><td>720p</td><td>3–5 Mbps</td></tr><tr><td>1080p</td><td>5–8 Mbps</td></tr><tr><td>4K</td><td>20–50 Mbps</td></tr></tbody></table><h3 id="码率的编码模式" tabindex="-1">码率的编码模式 <a class="header-anchor" href="#码率的编码模式" aria-label="Permalink to &quot;码率的编码模式&quot;">​</a></h3><p><strong>CBR（Constant Bitrate，恒定码率）</strong></p><ul><li>在整个视频或流媒体过程中，编码器尽量维持一个固定的码率。</li><li>优点：网络带宽预测性好、播放器或设备兼容性高。</li><li>缺点：视频内容简单时仍用很多比特，浪费；内容复杂时可能无法提供足够质量，因为码率受限。</li><li>适用场景：直播推流、需要固定带宽的场合、设备或网络不允许码率变化的场景。</li></ul><p><strong>VBR（Variable Bitrate，可变码率）</strong></p><ul><li>码率随视频内容复杂度变化：场景静止或简单时码率低；运动、复杂场景时码率高。</li><li>优点：更有效利用码率资源，能在保证质量的同时节省带宽／存储。</li><li>缺点：网络带宽需求和码率峰值不可预测；如果设备或网络不能很好适应变化，可能出现缓冲或播放问题。</li><li>适用场景：点播视频、存储优化、网络带宽较好且允许波动的场景。</li></ul><p><strong>QVBR（Quality-Defined Variable Bitrate，质量定义可变码率）</strong></p><ul><li>是比 VBR 更进一步的控制模式。编码器根据“目标质量”而不是“目标平均码率”来分配比特。即：你定义“质量级别” + 最大码率，编码器尝试用尽可能低码率达到该质量。</li><li>特点： <ul><li>不追求固定平均码率，而追求稳定的视觉质量。</li><li>你可以设置最大码率以限制带宽峰值。</li></ul></li><li>优点：在内容复杂度变化大的情况下，能提供更一致的视觉质量，同时在简单场景节省比特。</li><li>缺点：如果设备或网络对码率峰值敏感，需要严格控制最大码率。对于一些旧设备或协议可能兼容性稍差。</li><li>适用场景：OTT 流媒体、点播、大规模分发，带宽／存储成本需要优化同时质量要求较高。</li></ul><p><strong>CVBR（Constrained Variable Bitrate，受限可变码率）</strong></p><ul><li>可以看成是 “VBR + 约束” 的一种：虽然码率可变，但有一个最大（或最小）码率限制，以避免码率飙升到不可控状态。</li><li>优点：兼顾 VBR 的灵活性和 CBR 的带宽可控性。</li><li>缺点：仍然不是固定码率，设备／网络仍需应对变化；质量可能被最大码率限制住。</li><li>适用场景：直播或分发中，希望码率灵活但不能超出某一上限的场合。</li></ul><p><strong>ABR（Average Bitrate，平均码率）</strong></p><ul><li>通常指的是编码/传输过程中，以一个目标“平均码率”作为参考，编码器波动但最终平均值趋近这个目标。</li><li>在一些文档中，ABR 也用于直播中的 “自适应码率流”（Adaptive Bitrate Streaming），不过这里我们谈的是编码层面。</li><li>优点：比 CBR 更有效率，比完全无约束的 VBR更可控。</li><li>缺点：仍有场景下码率高峰可能导致带宽压力。</li></ul><p><strong>比较表格：</strong></p><table tabindex="0"><thead><tr><th>模式</th><th>全称</th><th>控制目标</th><th>码率变化情况</th><th>曲线形态</th><th>含义</th><th>典型适用场景</th></tr></thead><tbody><tr><td>CBR</td><td>Constant Bitrate</td><td>固定码率</td><td>基本不变化</td><td>▬▬▬▬▬▬▬▬▬▬（平直线）</td><td>每一秒码率几乎不变。</td><td>直播推流、带宽严格受限场景</td></tr><tr><td>VBR</td><td>Variable Bitrate</td><td>平均码率目标</td><td>高复杂度↑，低复杂度↓</td><td>╰╮╭╯╰╮╭╯（上下波动）</td><td>复杂画面高、简单画面低。</td><td>点播、存储、网络带宽好可波动场景</td></tr><tr><td>QVBR</td><td>Quality-Defined VBR</td><td>目标视觉质量 + 最大码率</td><td>根据质量变化，码率高峰有控制</td><td>类似 VBR，但更关注“质量线”</td><td>视觉质量保持稳定。</td><td>OTT／VOD 分发、高质量要求场景</td></tr><tr><td>CVBR</td><td>Constrained VBR</td><td>变动码率 + 上限约束</td><td>变动但不可超过设定峰值</td><td>╰╮╭╯╰╮╭╯（但顶部被截平）</td><td>可变，但有上限。</td><td>直播或分发中，需控制最大带宽但想灵活</td></tr><tr><td>ABR</td><td>Average Bitrate (模式)</td><td>目标平均码率</td><td>变动，但最终平均接近目标</td><td>综合控制平均值的 VBR</td><td></td><td></td></tr></tbody></table>`,77)])])}const u=d(s,[["render",l]]);export{g as __pageData,u as default};
